import { describe, it } from "vitest";

describe("quote", () => {
  it.todo("empty item list -> premium 5 (only the processing fee)");
  it.todo("newcomer plain sword -> 100 base + 10 first insurance + 5 fee = 115");
  it.todo("newcomer plain amulet -> 60 base + 6 first insurance + 5 fee = 71");
  it.todo("newcomer plain staff -> 80 base + 8 first insurance + 5 fee = 93");
  it.todo("newcomer plain potion -> 40 base + 4 first insurance + 5 fee = 49");
  it.todo("2 runes -> base 50 -> premium 60");
  it.todo("3 runes -> block base 60 -> premium 71");
  it.todo("4 runes -> no block, base 100 -> premium 115");
  it.todo("7 runes -> no block, base 175 -> 197.5 rounded up in MHPCO's favor to 198");
  it.todo("1 moonstone -> base 25 -> 32.5 rounded up to 33");
  it.todo("2 runes + 1 moonstone -> no block across types, base 75 -> 87.5 rounded up to 88");
  it.todo("3 runes + 3 moonstones -> two separate blocks, base 120 -> premium 137");
  it.todo("newcomer cursed steel sword enchantment 3 -> premium 165");
  it.todo("cursed sword + plain amulet -> surcharge only on sword: 160 + 50 + 16 + 5 = 231");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge: 100 + 30 + 10 + 5 = 145");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge: 115");
  it.todo("cursed sword with enchantment 5 -> both surcharges: 100 + 50 + 30 + 10 + 5 = 195");
  it.todo("cursed sword with enchantment 4 -> curse surcharge only: 165");
  it.todo("amulet with enchantment 6 -> surcharge on amulet base: 60 + 18 + 6 + 5 = 89");
  it.todo("customer with exactly 2 years -> loyalty discount: 100 - 20 + 10 + 5 = 95");
  it.todo("customer with 1 year -> no loyalty discount: 115");
  it.todo("second quote in scenario -> follow-up discount: 100 + 10 - 15 + 5 = 100");
  it.todo("third quote in scenario -> follow-up discount again: 100");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -> 175 then 160");
});

describe("claim", () => {
  it.todo("schema example: loyal customer's amulet, damage 200 -> payout 100, remainingCap 1100");
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remainingCap 1600");
  it.todo("rune (insurance value 250), damage 200 -> payout 100, remainingCap 400");
  it.todo("dragon sword enchantment 9, damage 1000 -> 50% rule wins, payout 400");
  it.todo("dragon sword enchantment 5, damage 800 -> full reimbursement, payout 700");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400");
  it.todo("dragon sword with exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("sword enchantment 8, damage 901 -> 350.5 rounded down to 350, remainingCap 1650");
  it.todo("dragon attack on sword (500) and amulet (300) -> deductible per item, payout 600, cap 3200 -> remainingCap 2600");
  it.todo("two swords, both damaged 500 -> separate deductibles, payout 800, cap 4000 -> remainingCap 3200");
  it.todo("cursed sword cap based on unmodified value: damage 500 -> payout 400, remainingCap 1600");
  it.todo("sword + 3 runes insurance sum 1750, damage sword 500 -> payout 400, remainingCap 3100");
  it.todo("two successive claims of 1500 on a sword -> 1400/600 then 600/0");
});

describe("rejected scenarios (runScenario throws an Error)", () => {
  it.todo("quote with unknown item type broomstick -> throws");
  it.todo("claim damage to an amulet when only a sword is insured -> throws");
  it.todo("claim damage to an unknown item type -> throws");
  it.todo("claim with two sword damages but only one sword insured -> throws");
  it.todo("claim with damage amount -200 -> throws");
});

