import { policyBasePremium, type Item } from "./priceList.js";

export type { Item } from "./priceList.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const WHOLE_IN_PERCENT = 100;

const percentOf = (amount: number, percent: number): number => (amount * percent) / WHOLE_IN_PERCENT;

function quote(items: Item[]): number {
  const base = policyBasePremium(items);
  return base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): Result[] {
  return scenario.steps.map((step) => ({ premium: step.op === "quote" ? quote(step.items) : PROCESSING_FEE }));
}
